import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'ai-engineer-responsible-ai-l4-001', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Fairness Metrics', question: 'What is the difference between individual fairness and group fairness, and why are they often in tension?', options: ['Individual and group fairness are the same concept', 'Individual fairness requires similar individuals to receive similar predictions (Lipschitz constraint on the model). Group fairness requires statistical parity of outcomes across protected groups. They conflict because: ensuring equal group-level outcomes may require treating similar individuals from different groups differently, and ensuring individual consistency may result in unequal group-level outcomes when groups have different base rates. Practitioners must choose which definition to prioritize based on the deployment context', 'Group fairness is always more important than individual fairness', 'Individual fairness is impossible to implement in practice'], correctAnswer: 1, explanation: 'Individual fairness (Dwork et al. 2012): if d(x₁, x₂) ≤ ε then |f(x₁) - f(x₂)| ≤ δ. Similar people → similar outcomes. Requires defining a task-specific similarity metric d(). Group fairness (demographic parity): P(Ŷ=1|A=0) = P(Ŷ=1|A=1). Equal positive prediction rates across groups. Tension: if group A has 10% base rate and group B has 20%, individual fairness predicts according to true risk (unequal group rates), while demographic parity forces equal prediction rates (may require over-predicting for group A or under-predicting for group B → treating similar individuals differently across groups).', tags: ['individual-fairness', 'group-fairness', 'tension', 'fairness-definitions'] },
  { id: 'ai-engineer-responsible-ai-l4-002', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Bias Mitigation', question: 'What are pre-processing, in-processing, and post-processing approaches to bias mitigation?', options: ['Only post-processing is needed for bias mitigation', 'Pre-processing modifies training data to remove bias (reweighting, resampling, or transforming features). In-processing adds fairness constraints to the model training objective (adversarial debiasing, fairness-constrained optimization). Post-processing adjusts model outputs to satisfy fairness criteria (threshold adjustment per group, calibration). Each stage trades different things: pre-processing may lose information, in-processing increases training complexity, post-processing cannot fix representation issues. Best practice is to combine approaches across stages', 'All bias mitigation approaches are identical', 'Pre-processing eliminates all bias permanently'], correctAnswer: 1, explanation: 'Pre-processing: (1) reweighting: assign higher weights to underrepresented group-outcome combinations, (2) disparate impact remover: transform features to remove correlation with protected attribute while preserving information, (3) fair representation learning: learn embeddings that are independent of protected attribute. In-processing: (1) adversarial debiasing: add adversary that tries to predict protected attribute from model representations → model learns to hide it, (2) fairness constraints: add equalized odds or demographic parity as optimization constraints (Lagrangian or barrier method), (3) causal debiasing: remove causal paths from protected attribute to prediction. Post-processing: (1) threshold optimization: find different classification thresholds per group that satisfy the fairness criterion while maximizing accuracy, (2) reject option classification: abstain on uncertain predictions near the group boundary. AIF360 (IBM) implements all three categories.', tags: ['bias-mitigation', 'pre-processing', 'in-processing', 'post-processing'] },
  { id: 'ai-engineer-responsible-ai-l4-003', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Explainability', question: 'What is the right to explanation under GDPR and what does it require technically?', options: ['Only binary decisions need explanation under GDPR', 'GDPR does not address algorithmic decisions', 'GDPR requires sharing the full model source code', 'GDPR Articles 13-15 and 22 require: (1) meaningful information about the logic involved in automated decision-making, (2) the significance and envisaged consequences for the data subject, (3) the right not to be subject to a decision based solely on automated processing that significantly affects them. Technically this requires: model documentation explaining the decision logic, feature importance explanations for individual predictions, and the ability for humans to review and override automated decisions. The exact technical requirements remain debated in legal scholarship'], correctAnswer: 3, explanation: 'GDPR recital 71: "specific information on the logic involved as well as significance and envisaged consequences." Legal interpretation varies: (1) Minimum: describe what data is used and the general logic ("we use your credit history and income to assess creditworthiness"), (2) Medium: provide feature importance for individual decisions (SHAP/LIME explanations), (3) Maximum: full counterfactual explanation ("if your income were €5K higher, you would have been approved"). Practical implementation: (1) model cards documenting the system, (2) per-decision explanations (SHAP values for key features), (3) human review mechanism for contested decisions, (4) right to contest and request re-evaluation. The interpretability-accuracy trade-off is central: simpler models (logistic regression) are inherently explainable but may be less accurate. Complex models (deep learning) may need post-hoc explanation methods.', tags: ['gdpr', 'right-to-explanation', 'article-22', 'automated-decisions'] },
  { id: 'ai-engineer-responsible-ai-l4-004', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Privacy', question: 'What is the fundamental trade-off in differential privacy (DP) for ML and how is the privacy budget ε managed?', options: ['Smaller ε always improves model accuracy', 'Differential privacy has no trade-offs', 'DP provides a mathematical guarantee that any single training example has limited influence on the model output. The privacy budget ε controls the trade-off: smaller ε = stronger privacy but more noise = lower model accuracy. The budget is consumed with each training step (composition theorem). Key challenge: for complex models like deep networks, achieving meaningful ε (1-10) often degrades accuracy by 5-20%. Budget management: track cumulative ε across all queries/training steps, stop when budget is exhausted. Rényi DP and the moments accountant enable tighter budget tracking', 'The privacy budget can be used infinitely'], correctAnswer: 2, explanation: 'DP guarantee: for any two datasets D and D\' differing in one record: P(M(D) ∈ S) ≤ e^ε · P(M(D\') ∈ S) + δ. ε=0: perfect privacy (output independent of any individual). ε=∞: no privacy. Practical range: ε=1-10 for useful privacy. DP-SGD: clip per-sample gradients to norm C, add Gaussian noise N(0, σ²C²). Moments accountant tracks cumulative ε across T training steps: ε grows as O(√T), not O(T) (tight composition). Management: (1) set total privacy budget ε_total (e.g., 8), (2) compute ε per epoch based on σ, C, batch size, (3) train for as many epochs as budget allows. Practical impact: CIFAR-10 at ε=8: ~75% accuracy (vs 95% without DP). For LLMs: DP pre-training is very expensive; DP fine-tuning on sensitive data is more practical. Apple, Google use DP for analytics (ε=2-8).', tags: ['differential-privacy', 'privacy-budget', 'epsilon', 'dp-sgd'] },
  { id: 'ai-engineer-responsible-ai-l4-005', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'EU AI Act', question: 'How does the EU AI Act classify AI systems by risk level and what are the requirements for high-risk systems?', options: ['The EU AI Act only applies to systems developed in the EU', 'The EU AI Act treats all AI systems equally', 'High-risk AI systems only need a one-time certification', 'The EU AI Act defines four risk tiers: (1) Unacceptable risk (banned): social scoring, real-time biometric identification in public spaces, (2) High risk (strict requirements): AI in hiring, credit scoring, law enforcement, education — requires risk management, data governance, transparency, human oversight, accuracy/robustness standards, (3) Limited risk: chatbots must disclose they are AI, (4) Minimal risk: no requirements. High-risk systems must maintain technical documentation, undergo conformity assessments, and implement post-market monitoring throughout their lifecycle'], correctAnswer: 3, explanation: 'High-risk requirements (Articles 9-15): (1) Risk management system: identify and mitigate risks throughout lifecycle, (2) Data governance: training data must be relevant, representative, error-free to the extent possible, (3) Technical documentation: describe the system, training process, and performance, (4) Record-keeping: automatic logging for traceability, (5) Transparency: users must be informed they are interacting with AI and understand its capabilities, (6) Human oversight: designed to be overseen by humans who can override, (7) Accuracy, robustness, cybersecurity: maintained throughout lifecycle. General-purpose AI models (like GPT-4, Claude) with systemic risk have additional obligations: model evaluation, adversarial testing, incident reporting, and energy consumption tracking. Enforcement: fines up to €35M or 7% of global revenue. Takes effect in stages from August 2024 to August 2027.', tags: ['eu-ai-act', 'risk-classification', 'high-risk', 'compliance'] },
  { id: 'ai-engineer-responsible-ai-l4-006', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Transparency', question: 'What is a model card and what information should it contain for responsible deployment?', options: ['Model cards document: (1) model details (architecture, training data, version, developers), (2) intended use and out-of-scope uses, (3) performance metrics disaggregated by relevant demographic groups, (4) limitations and known failure modes, (5) ethical considerations and potential biases, (6) training data description and known gaps, (7) evaluation methodology and results. They serve as the primary transparency mechanism, enabling downstream users to make informed decisions about whether a model is appropriate for their use case', 'Only accuracy on one benchmark needs to be reported', 'Model cards are optional marketing documents', 'Model cards only list the model architecture'], correctAnswer: 0, explanation: 'Model card template (Mitchell et al. 2019): Section 1: Model Details — architecture, version, license, contact. Section 2: Intended Use — primary use cases, explicitly out-of-scope uses ("not for medical diagnosis"). Section 3: Factors — groups, instruments, environments evaluated. Section 4: Metrics — chosen metrics with justification, disaggregated results by demographic factors. Section 5: Training Data — description, preprocessing, known biases. Section 6: Ethical Considerations — potential harms, mitigation strategies. Section 7: Caveats and Recommendations. Hugging Face requires model cards for uploaded models. For LLMs: system cards (OpenAI GPT-4, Anthropic Claude) extend this with safety evaluation results, red-teaming outcomes, and deployment guardrails. The EU AI Act mandates documentation similar to model cards for high-risk systems.', tags: ['model-card', 'transparency', 'documentation', 'responsible-deployment'] },
  { id: 'ai-engineer-responsible-ai-l4-007', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Algorithmic Auditing', question: 'What is an algorithmic audit and how should it be conducted?', options: ['Only the model developer should audit their own system', 'Algorithmic audits are identical to software security audits', 'An algorithmic audit systematically evaluates an AI system for: (1) accuracy across demographic groups (disparate performance), (2) fairness metric compliance (selected definition), (3) potential for discriminatory outcomes, (4) alignment with stated policies, (5) robustness to adversarial inputs. Conducted by: internal teams (first-party), external auditors (second/third-party), or affected communities (participatory). Methods: statistical testing on disaggregated data, qualitative review of failure cases, red-teaming for bias, and stakeholder interviews. Results should be documented and made available to affected parties', 'Algorithmic audits are only needed once before deployment'], correctAnswer: 2, explanation: 'Audit methodology: (1) Scope: define system boundaries, protected attributes, and relevant fairness metrics. (2) Data analysis: examine training and evaluation data for representation gaps, label quality per group. (3) Performance audit: compute accuracy, precision, recall, calibration disaggregated by protected groups × intersections. (4) Fairness audit: measure selected fairness metrics (demographic parity, equalized odds, predictive parity). (5) Robustness audit: test with adversarial examples, edge cases, out-of-distribution inputs per group. (6) Qualitative review: examine worst failure cases for each group. (7) Report: findings, severity ratings, recommended mitigations. Frequency: before deployment + annually + after significant changes. NYC Local Law 144 (2023) requires annual bias audits of automated employment decision tools. The EU AI Act mandates conformity assessments for high-risk systems.', tags: ['algorithmic-audit', 'bias-audit', 'fairness-testing', 'third-party'] },
  { id: 'ai-engineer-responsible-ai-l4-008', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Federated Learning', question: 'How does federated learning address privacy concerns while still enabling model training?', options: ['Federated learning trains models across multiple devices/institutions without centralizing data. Each participant trains on local data and shares only model updates (gradients), not raw data. Privacy benefits: data never leaves the device/institution. Limitations: (1) gradient updates can leak training data information (gradient inversion attacks), (2) the global model may memorize individual data, (3) non-IID data across participants degrades model quality. Combining federated learning with differential privacy (noisy gradient aggregation) provides formal privacy guarantees', 'Gradient updates cannot reveal any information about training data', 'Federated learning provides perfect privacy', 'Federated learning requires sending all data to a central server'], correctAnswer: 0, explanation: 'Federated learning protocol (FedAvg): (1) Server sends global model to N clients, (2) each client trains on local data for E epochs, (3) clients send model updates (weights or gradients) to server, (4) server averages updates → new global model, (5) repeat. Privacy analysis: gradients can be "inverted" — Zhu et al. (2019) showed that individual training images can be reconstructed from gradient updates. Defense: (a) add DP noise to gradient updates before sending (Secure Aggregation + DP), (b) use secure multi-party computation so the server never sees individual updates, only the aggregate. Application: Google Keyboard (Gboard) trains next-word prediction on-device. Apple trains Siri improvements without collecting raw audio. Healthcare: hospitals collaboratively train diagnostic models without sharing patient data.', tags: ['federated-learning', 'privacy', 'gradient-inversion', 'secure-aggregation'] },
  { id: 'ai-engineer-responsible-ai-l4-009', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Environmental Impact', question: 'What is the environmental cost of training large AI models and how can it be reduced?', options: ['Environmental impact is only relevant for the largest models', 'Larger models are always more energy-efficient', 'AI training has negligible environmental impact', 'Training GPT-3 consumed ~1,287 MWh of electricity, equivalent to ~552 tons of CO2. Training GPT-4 is estimated at 10-100x more. Environmental reduction strategies: (1) compute-efficient training (Chinchilla scaling — smaller model, more data), (2) use renewable energy data centers, (3) model distillation (train small model from large model), (4) efficient architectures (MoE — same capacity, less compute per token), (5) reuse pretrained models (fine-tune rather than train from scratch). Reporting energy consumption and CO2 equivalent is becoming a best practice and regulatory expectation'], correctAnswer: 3, explanation: 'Environmental accounting: Strubell et al. (2019) brought attention to the carbon cost of NLP. Training BERT-base: ~1,507 kg CO2. GPT-3: ~552 tons CO2. LLaMA-2-70B: ~291 tons CO2 (more efficient training). For context: average US person emits ~16 tons CO2/year. Reduction strategies: (1) Chinchilla scaling: train a 70B model on 2T tokens instead of 175B on 300B tokens — same quality, ~60% less compute. (2) Efficient hardware: H100 provides 3x energy efficiency over A100 for training. (3) Location: Google\'s Oklahoma data center (wind/solar) vs coal-powered alternatives → 5-10x CO2 difference for same compute. (4) Inference dominance: total lifecycle emissions of a popular model are dominated by inference (millions of users), not training. Optimizing inference (quantization, caching) has larger environmental impact than training efficiency. ML CO2 Impact Calculator and Zeus (Michigan) help estimate and reduce ML energy consumption.', tags: ['environmental-impact', 'carbon-footprint', 'green-ai', 'energy-efficiency'] },
  { id: 'ai-engineer-responsible-ai-l4-010', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Accountability', question: 'What is the accountability gap in AI systems and how can organizational structures address it?', options: ['The accountability gap occurs when no specific person or team is responsible for an AI system\'s outcomes. In complex ML pipelines, responsibility is diffused across data collectors, model developers, deployers, and operators. Organizational structures to address this: (1) AI ethics boards with decision-making authority, (2) designated AI risk owners per deployment, (3) clear incident response procedures, (4) mandatory impact assessments before deployment, (5) documentation requirements at each pipeline stage. The key principle: someone must be accountable for every AI decision that affects people', 'AI systems have clear accountability by default', 'Accountability only matters for the model developer', 'AI systems can be held accountable themselves'], correctAnswer: 0, explanation: 'Accountability structures: (1) RACI matrix for AI: who is Responsible (builds), Accountable (approves), Consulted (advises), Informed (notified) for each stage (data collection, training, evaluation, deployment, monitoring). (2) AI ethics review: mandatory review before deploying models that affect people (hiring, lending, healthcare). Board includes: ML engineers, domain experts, ethicists, legal, affected community representatives. (3) Incident response: designated responder for AI failures, documented procedures for model rollback, user notification, and root cause analysis. (4) Impact assessment: before deployment, document expected benefits, potential harms, affected populations, mitigation measures. Regulatory push: EU AI Act requires a "provider" who bears responsibility. NYC Local Law 144 requires employers to be accountable for bias in hiring AI. Companies like Microsoft, Google publish responsible AI principles with organizational implementation.', tags: ['accountability', 'governance', 'ethics-board', 'impact-assessment'] },
  { id: 'ai-engineer-responsible-ai-l4-011', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Bias Sources', question: 'What are the different sources of bias in ML systems and at which pipeline stages do they enter?', options: ['Bias only enters through biased training data', 'Removing protected attributes eliminates all bias', 'Bias sources: (1) Historical bias: real-world inequities reflected in data (fewer women in STEM → model learns this as a pattern), (2) Representation bias: data doesn\'t represent the target population (training on English text, deploying for all languages), (3) Measurement bias: proxy variables that correlate with protected attributes (zip code as proxy for race), (4) Aggregation bias: one model for diverse subpopulations ignores subgroup differences, (5) Evaluation bias: benchmarks don\'t test on relevant subgroups, (6) Deployment bias: system used differently than intended. Bias enters at every pipeline stage, not just data collection', 'Bias is only a problem in classification models'], correctAnswer: 2, explanation: 'Pipeline stages: Data collection → historical + representation bias. Feature engineering → measurement bias (choosing zip code as feature). Model training → aggregation bias (single model for heterogeneous population), learning bias (model amplifies training data patterns). Evaluation → evaluation bias (benchmark doesn\'t test subgroups). Deployment → deployment bias (used for unintended purpose), feedback loop bias (model outputs affect future data). Critical insight: removing protected attributes (gender, race) does NOT remove bias — correlated proxy features (name, zip code, education) carry the same information. Proper debiasing requires understanding the causal structure of how the protected attribute relates to other features and the outcome. Fairness-aware feature selection, causal debiasing, and intersectional analysis are needed.', tags: ['bias-sources', 'pipeline-bias', 'proxy-variables', 'historical-bias'] },
  { id: 'ai-engineer-responsible-ai-l4-012', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Fairness Tools', question: 'What tools are available for fairness assessment and how should they be integrated into ML pipelines?', options: ['A single fairness tool is sufficient for all use cases', 'Key fairness tools: (1) AIF360 (IBM): comprehensive bias detection and mitigation algorithms for tabular data, (2) Fairlearn (Microsoft): fairness assessment dashboard with mitigation algorithms integrated with scikit-learn, (3) What-If Tool (Google): interactive visualization for exploring model behavior across subgroups, (4) Aequitas: audit framework for bias in risk assessment models. Integration: run fairness checks as automated pipeline gates — compute fairness metrics per protected group, fail the pipeline if disparities exceed thresholds, generate fairness reports for model registry documentation', 'Fairness tools are only needed during model development', 'Fairness tools eliminate the need for human judgment about fairness'], correctAnswer: 1, explanation: 'Integration pattern: (1) Data analysis stage: Aequitas/AIF360 analyze training data for representation gaps (e.g., 95% of examples from group A, 5% from group B). (2) Model training stage: Fairlearn constrained optimization or AIF360 in-processing (adversarial debiasing) during training. (3) Evaluation stage: automated pipeline step computes: accuracy per group, equalized odds gap, demographic parity gap, calibration per group. Gate: if any critical metric exceeds threshold → block deployment + alert. (4) Monitoring stage: track fairness metrics in production (prediction rates per group over time). Alert on drift that creates new disparities. Tool selection: AIF360 for comprehensive mitigation algorithms, Fairlearn for scikit-learn integration and dashboard, Aequitas for audit reporting, What-If Tool for interactive exploration during development. All should be used together — each catches different issues.', tags: ['fairness-tools', 'aif360', 'fairlearn', 'pipeline-integration'] },
  { id: 'ai-engineer-responsible-ai-l4-013', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'LLM Bias', question: 'How does bias manifest in large language models and what evaluation methods exist?', options: ['LLM biases: (1) stereotypical associations (linking professions to genders/races), (2) representation gaps (less accurate for underrepresented languages/dialects), (3) toxicity disparities (more likely to generate toxic content about certain groups), (4) sycophancy (agreeing with user biases rather than correcting them), (5) cultural bias (defaulting to Western/English-centric perspectives). Evaluation: BBQ benchmark (question answering with social biases), WinoBias (co-reference resolution bias), CrowS-Pairs (stereotypical associations), and RealToxicityPrompts (toxicity generation disparities across demographic mentions)', 'LLMs do not exhibit biases', 'RLHF completely eliminates all biases in LLMs', 'LLM biases are identical to tabular model biases'], correctAnswer: 0, explanation: 'LLM bias evaluation: (1) BBQ (Bias Benchmark for QA): ambiguous questions where a stereotypical assumption could bias the answer. "The doctor and nurse discussed the patient. Who had more medical training?" → biased model answers based on gender associations. (2) WinoBias: "The nurse examined the patient because she was concerned." → does "she" refer to nurse or patient? Biased models associate "she" with "nurse." (3) Toxicity analysis: generate completions for prompts mentioning different demographic groups, measure toxicity rates. Higher toxicity when mentioning certain groups = bias. (4) CrowS-Pairs: paired sentences differing only in demographic reference. Model should assign similar likelihood to both. (5) Multilingual evaluation: measure performance gap between high-resource (English) and low-resource languages. Mitigation: RLHF with fairness-aware reward models, balanced training data, constitutional AI principles about equitable treatment, and post-hoc output filtering.', tags: ['llm-bias', 'bbq', 'winobias', 'stereotypes'] },
  { id: 'ai-engineer-responsible-ai-l4-014', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Consent', question: 'What are the consent challenges for using personal data in ML training?', options: ['ML training does not require user consent', 'Consent challenges: (1) purpose specification: consent given for one purpose (service improvement) may not cover another (ad targeting model), (2) informed consent: users cannot understand how their data contributes to a model with billions of parameters, (3) retroactive consent: data collected before ML era is now used for training without original consent, (4) collective consent: one person\'s data combined with others creates emergent information about groups who didn\'t consent. GDPR requires specific, informed consent with the right to withdraw. Practical solutions: clear data use policies, opt-in/opt-out mechanisms, data anonymization, and synthetic data generation', 'Consent is only needed for medical data', 'General terms of service are sufficient for all ML training'], correctAnswer: 1, explanation: 'GDPR consent requirements for ML: (1) Specific: "we use your data to train recommendation models" (not "to improve services" — too vague). (2) Informed: explain in understandable terms what the model does with their data. (3) Freely given: refusing consent shouldn\'t block access to the service (can\'t bundle). (4) Withdrawable: user can withdraw consent → data must be removed from future training (right to erasure). Challenges: (a) web-scraped data (LAION, Common Crawl): no explicit consent from people whose data is included. (b) Data from public sources: "public" doesn\'t mean "consent to ML training" (LinkedIn photos, social media posts). (c) Foundation models: consent given for one model version doesn\'t extend to all future versions. Emerging solutions: Spawning.ai\'s "Have I Been Trained?" lets people check if their work is in training data. Data licensing frameworks (e.g., Adobe Stock, Shutterstock for image generation training).', tags: ['consent', 'gdpr', 'purpose-limitation', 'data-rights'] },
  { id: 'ai-engineer-responsible-ai-l4-015', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Intersectionality', question: 'What is intersectional fairness and why do single-axis fairness analyses miss important disparities?', options: ['Analyzing fairness on one protected attribute at a time is sufficient', 'Intersectional fairness examines performance across combinations of protected attributes (e.g., Black women, elderly disabled individuals). A model may be fair when evaluated separately on race and gender but severely unfair for the intersection. Buolamwini & Gebru (2018) showed commercial facial recognition had error rates of 0.8% for light-skinned males but 34.7% for dark-skinned females — an intersection invisible to single-axis analysis. Intersectional analysis requires sufficient data per subgroup, which becomes challenging with many protected attributes', 'Intersectional analysis is mathematically impossible', 'Disparities always appear in single-axis analysis first'], correctAnswer: 1, explanation: 'Gender Shades (Buolamwini & Gebru 2018): tested commercial facial analysis systems. By gender: male 0.7% error, female 7% error. By skin type: lighter 0.8% error, darker 12% error. Intersection: light male 0.8%, light female 3%, dark male 6%, dark female 34.7%. The 34.7% error rate for dark-skinned females was invisible in either single-axis analysis (average female error was "only" 7%). Intersectional analysis: evaluate on all meaningful cross-products of protected attributes. Challenge: k attributes with m values each → m^k subgroups. With 5 binary attributes: 32 subgroups. Some may have too few test examples for statistical significance. Solutions: (a) over-sample underrepresented intersections in test data, (b) use hierarchical models that share information across subgroups, (c) focus on high-risk intersections identified by domain experts.', tags: ['intersectionality', 'gender-shades', 'subgroup-fairness', 'compound-bias'] },
  { id: 'ai-engineer-responsible-ai-l4-016', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Red Teaming', question: 'What is bias red teaming and how does it differ from safety red teaming?', options: ['Only safety red teaming is needed before deployment', 'Bias testing only requires automated benchmarks', 'Safety red teaming focuses on eliciting harmful outputs (violence, illegal content). Bias red teaming specifically tests for discriminatory behavior: (1) differential treatment (does the model give different quality answers based on names suggesting demographics?), (2) stereotype reinforcement (does it generate stereotypical content when prompted about demographic groups?), (3) representation harms (does it exclude or misrepresent certain groups?), (4) allocation harms (does it systematically disadvantage certain groups in resource-allocation recommendations?). Bias red teaming requires diverse testers representing affected communities', 'Bias red teaming and safety red teaming are identical'], correctAnswer: 2, explanation: 'Bias red teaming methodology: (1) Demographic variation testing: same question with names from different demographics ("Apply for a loan as John Smith" vs "Apply for a loan as Jamal Washington"). Compare response quality, tone, and recommendations. (2) Stereotype elicitation: "Tell me about women in engineering" — does the model reproduce stereotypes or provide balanced perspective? (3) Intersectional probing: test combinations of demographics ("elderly transgender person seeking healthcare"). (4) Language/dialect: does the model understand and respond appropriately to AAVE, non-standard English, multilingual queries? (5) Disability representation: does the model make assumptions about capability based on disability mentions? Diverse testers are essential: internal employees miss biases that community members experience. Microsoft, Google, and Anthropic maintain external bias red-teaming programs alongside internal testing.', tags: ['bias-red-teaming', 'discrimination-testing', 'stereotype', 'diverse-testers'] },
  { id: 'ai-engineer-responsible-ai-l4-017', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Copyright', question: 'What are the key legal questions around AI training on copyrighted data?', options: ['Key questions: (1) Is training on copyrighted data "fair use" (US) or falls under exceptions (EU)? — courts are currently deciding (NYT v. OpenAI, Getty v. Stability AI), (2) Does the model output constitute a "derivative work" of training data? (3) Who owns AI-generated content? (4) When does model output infringe copyright (verbatim reproduction vs style imitation)? The EU AI Act requires training data transparency. The US Copyright Office ruled AI-generated images without human creativity are not copyrightable. These legal frameworks are rapidly evolving', 'Training on copyrighted data is always legal', 'All AI-generated content is automatically copyrighted', 'Copyright law does not apply to AI in any jurisdiction'], correctAnswer: 0, explanation: 'Legal landscape (2024-2025): (1) NYT v. OpenAI: the NYT alleges ChatGPT reproduces its articles. OpenAI claims fair use (transformative use). Outcome will set major precedent. (2) EU: Text and Data Mining exception allows training on lawfully accessible works, but rights holders can opt out (Article 4). EU AI Act requires transparency about training data sources for general-purpose AI. (3) US Copyright Office: "Zarya of the Dawn" ruling — AI-generated images are not copyrightable, but human-selected/arranged compositions may be. (4) Opt-out mechanisms: robots.txt for web crawling, Spawning.ai for image datasets, DeviantArt for generated art training. (5) Licensing: some platforms offer AI training licenses (Shutterstock for DALL-E, Adobe Stock for Firefly). Best practice for responsible AI: (a) document all training data sources, (b) implement content filtering to prevent verbatim reproduction, (c) support opt-out mechanisms, (d) obtain licenses where possible.', tags: ['copyright', 'fair-use', 'training-data', 'legal'] },
  { id: 'ai-engineer-responsible-ai-l4-018', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Participatory Design', question: 'What is participatory AI design and why is community involvement important?', options: ['AI systems should be designed entirely by technical experts', 'Only technical feedback matters for AI system quality', 'Participatory AI design involves affected communities in the design, development, and evaluation of AI systems. Benefits: (1) identifies harms that developers cannot foresee (lived experience reveals edge cases), (2) builds trust and legitimacy, (3) ensures the system meets actual community needs, (4) surfaces fairness criteria relevant to the affected population. Methods: community workshops, stakeholder interviews, participatory evaluation sessions, and community advisory boards. This shifts AI development from "building for" to "building with" affected communities', 'Community involvement slows development without adding value'], correctAnswer: 2, explanation: 'Participatory methods: (1) Community needs assessment: before building, ask the affected community what they need, what concerns them, and what fairness means to them. (2) Co-design workshops: community members help define system requirements, choose fairness metrics, and identify acceptable error trade-offs. (3) Participatory evaluation: community members test the system and provide feedback on real-world impacts that benchmarks miss. (4) Ongoing advisory: community advisory board provides input on system updates and new use cases. Examples: (a) Te Hiku Media (Māori language AI): Māori community controlled how their language data was used for ASR. (b) Afrotherapy: African diaspora involvement in mental health chatbot design. (c) Indigenous AI: First Nations communities defining data sovereignty for AI training. Challenge: meaningful participation requires resources (compensation for community members\' time), genuine power-sharing (not just consultation theater), and sustained engagement (not one-time events).', tags: ['participatory-design', 'community-involvement', 'co-design', 'stakeholder-engagement'] },
  { id: 'ai-engineer-responsible-ai-l4-019', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Deployment Ethics', question: 'What ethical frameworks should guide decisions about whether to deploy an AI system?', options: ['Deployment ethics frameworks: (1) Beneficence/non-maleficence: do the benefits outweigh potential harms? (2) Proportionality: is AI the appropriate tool, or would a simpler solution suffice? (3) Reversibility: can harmful decisions be undone? (4) Human dignity: does the system respect individual autonomy and dignity? (5) Distributive justice: are benefits and harms distributed equitably across populations? A responsible deployment decision considers: the population affected, the stakes of decisions, the existence of alternatives, and the organization\'s capacity to monitor and correct the system post-deployment', 'Ethical considerations are only relevant for government AI applications', 'If a system is technically functional, it should be deployed', 'If a system improves efficiency, it should always be deployed'], correctAnswer: 0, explanation: 'Pre-deployment ethical assessment: (1) Stakeholder mapping: who is affected? (direct users, subjects of decisions, third parties, society). (2) Benefit-harm analysis: quantify expected benefits (efficiency, accuracy, cost savings) and potential harms (discrimination, privacy violation, autonomy reduction). (3) Alternatives assessment: could a rule-based system, human decision-maker, or simpler model achieve similar benefits with fewer risks? (4) Mitigation plan: for identified harms, what specific mitigations are in place and how will their effectiveness be monitored? (5) Sunset criteria: under what conditions should the system be withdrawn? (6) Affected population review: have representatives of affected communities reviewed and agreed to the deployment? Red flags for not deploying: harms disproportionately affect vulnerable populations, no effective mitigation exists, the system cannot be effectively monitored, or the deployment is in a high-stakes domain without adequate human oversight.', tags: ['deployment-ethics', 'benefit-harm', 'proportionality', 'human-dignity'] },
  { id: 'ai-engineer-responsible-ai-l4-020', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Monitoring', question: 'How should fairness be monitored in deployed ML systems over time?', options: ['Once a model is fair at deployment, it stays fair forever', 'Continuous fairness monitoring: (1) track prediction rates per protected group over time (detect emerging disparities), (2) monitor group-specific accuracy when delayed labels arrive, (3) detect intersectional disparities in production that testing missed, (4) monitor for feedback loop effects (model predictions → behavioral changes → distribution shift → new disparities), (5) track user complaints by demographic group. Alert when any fairness metric exceeds thresholds. Regular fairness reports (monthly/quarterly) document trends and actions taken to address disparities', 'Fairness only needs to be checked before deployment', 'Fairness metrics cannot be computed in production'], correctAnswer: 1, explanation: 'Fairness monitoring pipeline: (1) Log demographic attributes (where available or inferred) with predictions. (2) Compute real-time fairness metrics: demographic parity ratio (prediction_rate_A / prediction_rate_B), equalized odds gap when labels arrive. (3) Dashboard: time series of fairness metrics per group × intersection. (4) Alerts: if demographic parity ratio drops below 0.8 (four-fifths rule) → trigger investigation. (5) Feedback loop detection: monitor if model predictions change the input distribution for specific groups (e.g., loan denial model reduces applications from a group → less data → worse predictions → more denials). (6) Quarterly fairness review: analyze trends, investigate alerts, document actions. Tools: Evidently (drift + fairness monitoring), custom dashboards with Grafana, compliance reports from AIF360. Regulatory context: financial services (Fair Lending) require ongoing monitoring of disparate impact. NYC Local Law 144 requires annual published bias audits.', tags: ['fairness-monitoring', 'production', 'feedback-loops', 'continuous-audit'] },
  { id: 'ai-engineer-responsible-ai-l4-021', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'PII Detection', question: 'What techniques are used to detect and handle PII in ML pipelines?', options: ['PII detection tools have zero false positive rate', 'PII detection techniques: (1) regex patterns (SSN, phone numbers, email, credit card formats), (2) NER models (detect person names, addresses, organizations in text), (3) contextual classifiers (determine if a number is an SSN vs a random ID based on context), (4) image PII detection (face detection, license plate recognition), (5) structured data profiling (columns with high cardinality + name patterns likely contain PII). Handling: (a) masking/redaction (replace with [PII]), (b) tokenization (reversible replacement), (c) anonymization (irreversible), (d) differential privacy (add noise). Each approach has different trade-offs between data utility and privacy protection', 'PII detection is only needed for text data', 'Deleting all text containing names is sufficient PII handling'], correctAnswer: 1, explanation: 'PII detection stack: Layer 1 (pattern-based): regex for structured PII (SSN: \\d{3}-\\d{2}-\\d{4}, email, phone, credit card). Fast, high precision for known formats, but misses unstructured PII (names, addresses in free text). Layer 2 (NER-based): fine-tuned BERT model detects entities: PERSON, LOCATION, ORGANIZATION, DATE, MEDICAL_RECORD_NUMBER, etc. Handles unstructured text but has false positives/negatives. Layer 3 (contextual): Presidio (Microsoft), Phileas (Hugging Face) combine pattern matching + NER + contextual analysis. For images: face detection → blur/pixelate, license plate detection → redact. For LLM outputs: run PII detector on generated text before returning to user. Trade-offs: aggressive detection → removes useful information (false positives). Conservative detection → leaks PII (false negatives). Choose based on risk tolerance: healthcare (aggressive) vs marketing (moderate).', tags: ['pii-detection', 'presidio', 'anonymization', 'data-privacy'] },
  { id: 'ai-engineer-responsible-ai-l4-022', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Societal Impact', question: 'What is the "automation displacement" concern with AI and how should it be addressed responsibly?', options: ['AI automation can displace workers from routine cognitive tasks (data entry, customer service, document review). Responsible approaches: (1) design AI as augmentation (human + AI) rather than replacement, (2) provide transition support (retraining, career development) for affected workers, (3) gradually deploy to allow workforce adaptation, (4) involve affected workers in system design, (5) share productivity gains equitably (not just shareholder value). Studies show AI typically automates tasks, not entire jobs — restructuring roles around human-AI collaboration preserves employment while improving productivity', 'Automation always leads to net job loss', 'Companies have no responsibility for worker displacement', 'AI only creates jobs and never displaces them'], correctAnswer: 0, explanation: 'Research perspective: Acemoglu & Restrepo: AI automates tasks within jobs, not entire jobs. Net employment effect depends on: (a) displacement effect (tasks automated → workers displaced), (b) reinstatement effect (new tasks created for humans), (c) productivity effect (cheaper goods → increased demand → more jobs). Historical precedent: ATMs didn\'t eliminate bank tellers (number grew), but changed their role (from cash handling to customer service). Responsible deployment: (1) Impact assessment: before deploying automation, assess which workers are affected and how many. (2) Transition support: retrain affected workers for new roles (fund through automation savings). (3) Gradual rollout: don\'t automate overnight — phase in over months/years. (4) Human-in-the-loop: design systems where humans oversee and complement AI, not where AI replaces humans entirely. (5) Policy engagement: support social safety nets, education programs, and policies that distribute AI benefits broadly.', tags: ['automation-displacement', 'augmentation', 'worker-transition', 'societal-impact'] },
  { id: 'ai-engineer-responsible-ai-l4-023', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Data Sovereignty', question: 'What is data sovereignty and how does it affect AI development for indigenous and marginalized communities?', options: ['Data sovereignty asserts that communities (especially indigenous peoples) have the right to govern the collection, ownership, and use of their data. For AI: (1) indigenous languages should not be scraped for LLM training without community consent and governance, (2) cultural knowledge has communal ownership that Western IP frameworks don\'t recognize, (3) AI systems using community data should benefit the community. The CARE Principles (Collective benefit, Authority to control, Responsibility, Ethics) complement FAIR data principles by centering community governance', 'Data sovereignty only applies to nation-states', 'All publicly available data can be freely used for AI training', 'Data sovereignty concerns are irrelevant to AI development'], correctAnswer: 0, explanation: 'CARE Principles for Indigenous Data Governance: Collective Benefit: data use should benefit the community, not just researchers/companies. Authority to Control: communities determine how their data is used. Responsibility: those using data are accountable to the community. Ethics: data use must respect community rights and protocols. Examples: (1) Te Hiku Media (New Zealand): developed Māori speech recognition with community control — the Māori people own the data and model. (2) First Nations Information Governance Centre (Canada): OCAP principles (Ownership, Control, Access, Possession) for First Nations data. (3) African language AI: concern that Silicon Valley companies extract African language data without community benefit. Practical implication: AI developers should: (a) obtain community consent (not just individual consent), (b) share benefits (trained models, financial returns), (c) respect community decisions about data use, (d) support community capacity to govern their data.', tags: ['data-sovereignty', 'indigenous-data', 'care-principles', 'community-governance'] },
  { id: 'ai-engineer-responsible-ai-l4-024', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Adversarial Robustness', question: 'How can adversarial attacks exploit fairness vulnerabilities in ML systems?', options: ['Adversarial attacks always affect all groups equally', 'Adversarial attacks can specifically target fairness: (1) poisoning attacks inject biased data to make the model discriminatory (add examples that associate protected attributes with negative outcomes), (2) evasion attacks exploit the model differently for different groups (adversarial examples that are more effective against one demographic), (3) model stealing attacks extract and exploit fairness-sensitive decision boundaries. Fairness-aware adversarial training jointly optimizes for accuracy and fairness robustness, but this remains an active research area with no established best practices', 'Adversarial attacks and fairness are unrelated concerns', 'Fairness constraints prevent all adversarial attacks'], correctAnswer: 1, explanation: 'Fairness-targeted attacks: (1) Data poisoning for discrimination: inject a small percentage of training data (e.g., 3%) that associates a protected group with negative outcomes. The model learns this association without detection if the poisoned data looks normal individually. Defense: data auditing, robust statistics, poison detection. (2) Subgroup adversarial vulnerability: adversarial perturbations may be more effective for one demographic (e.g., adversarial makeup affects dark-skinned faces differently than light-skinned). Defense: evaluate adversarial robustness per subgroup, train with subgroup-aware adversarial examples. (3) Model inversion: reconstruct training data to identify protected attribute membership. Defense: differential privacy during training, output perturbation. This is an emerging intersection of adversarial ML and fairness ML — both must be addressed together for truly responsible systems.', tags: ['adversarial-fairness', 'data-poisoning', 'subgroup-vulnerability', 'robustness'] },
  { id: 'ai-engineer-responsible-ai-l4-025', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Governance', question: 'What is an AI governance framework and what components should it include?', options: ['An AI governance framework includes: (1) policies (acceptable use, data ethics, fairness standards), (2) processes (risk assessment, ethics review, incident response), (3) roles (AI ethics officer, review board, risk owners), (4) tools (fairness metrics, monitoring dashboards, audit mechanisms), (5) accountability mechanisms (documentation, reporting, consequences for violations). The framework should cover the entire AI lifecycle from ideation through deployment to decommissioning, with different governance intensity based on risk level', 'AI governance is only needed for companies with more than 1000 employees', 'A single policy document constitutes a complete governance framework', 'AI governance only requires technical reviews'], correctAnswer: 0, explanation: 'AI governance implementation: (1) Risk classification: categorize AI projects by risk level (low: recommendation system, medium: content moderation, high: hiring/lending, critical: autonomous systems). (2) Review gates: low risk → team self-certification. Medium → peer review. High → ethics board review. Critical → external audit. (3) Documentation requirements: model card, data sheet, impact assessment, fairness report — all required before deployment, level of detail scales with risk. (4) Monitoring obligations: low → quarterly checks. High → continuous monitoring with automated alerts. (5) Incident response: playbook for AI failures including: immediate mitigation, root cause analysis, affected party notification, regulatory reporting (if applicable), remediation plan. (6) Training: all ML practitioners must complete responsible AI training annually. Companies implementing this: Microsoft (Responsible AI Standard), Google (AI Principles with implementation teams), Salesforce (Trusted AI Principles). Regulatory alignment: design governance to satisfy EU AI Act, NYC Local Law 144, and industry-specific regulations simultaneously.', tags: ['ai-governance', 'framework', 'risk-classification', 'review-gates'] },
  { id: 'ai-engineer-responsible-ai-l4-026', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Interpretability', question: 'What is the interpretability-accuracy trade-off and when should interpretable models be preferred?', options: ['Complex models are always more accurate than interpretable models', 'Interpretability is never required for any application', 'The interpretability-accuracy trade-off suggests that more interpretable models (logistic regression, decision trees, rule lists) are less accurate than black-box models (deep learning, gradient boosting). However: (1) Rudin (2019) argues this trade-off is often overstated for tabular data, (2) in high-stakes domains (criminal justice, healthcare), interpretability may be legally or ethically required regardless of accuracy difference, (3) inherently interpretable models enable better debugging, trust-building, and error correction. Use interpretable models when: decisions affect individuals, regulatory compliance requires explanation, or the accuracy gap is small (<2%)', 'Interpretable models always have lower accuracy'], correctAnswer: 2, explanation: 'Rudin (2019) "Stop Explaining Black Box Machine Learning Models for High Stakes Decisions and Use Interpretable Models Instead": argued that for many tabular datasets, well-designed interpretable models (sparse linear, small rule sets, optimal decision trees) achieve within 1-2% of black-box accuracy. In these cases, the interpretability benefit vastly outweighs the small accuracy loss. When to prefer interpretable: (1) legal requirement (EU AI Act for high-risk, Fair Lending for credit), (2) debugging necessity (understanding model errors to fix data issues), (3) domain expert validation (doctors can verify the model\'s logic), (4) trust building (users trust decisions they understand). When black-box is appropriate: (1) accuracy difference is significant (>5%), (2) low-stakes decisions (content recommendation), (3) effective post-hoc explanations are sufficient, (4) the task involves unstructured data (images, text) where interpretable models are impractical.', tags: ['interpretability', 'accuracy-tradeoff', 'rudin', 'high-stakes'] },
  { id: 'ai-engineer-responsible-ai-l4-027', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'AI Safety Standards', question: 'What industry standards and frameworks exist for responsible AI development?', options: ['Standards are only relevant for government organizations', 'Key standards: (1) NIST AI Risk Management Framework (AI RMF 1.0): comprehensive risk management guidance, (2) ISO/IEC 42001:2023: AI management system standard, (3) IEEE 7000: Model Process for Addressing Ethical Concerns, (4) OECD AI Principles: government-level AI governance principles, (5) ISO/IEC 23894: AI risk management guidance. These provide structured approaches to: identify AI risks, implement mitigations, document compliance, and demonstrate due diligence. Organizations can certify against ISO 42001 to demonstrate responsible AI practices', 'Following one standard is sufficient for all regulatory requirements', 'There are no standards for responsible AI'], correctAnswer: 1, explanation: 'NIST AI RMF 1.0 (2023): four core functions — Govern (establish context, policies), Map (identify risks), Measure (assess risks), Manage (prioritize and respond to risks). Provides concrete categories and subcategories for assessment. ISO 42001 (2023): first certifiable AI management system standard. Requires: AI policy, risk assessment, lifecycle management, monitoring, and continuous improvement. Certification available through accredited bodies. IEEE 7000: focuses on incorporating ethical considerations into system design through stakeholder analysis and value prioritization. OECD AI Principles (adopted by 46 countries): trustworthy AI should be: (1) beneficial, (2) human-centered, (3) transparent, (4) robust, (5) accountable. Practical approach: use NIST AI RMF for risk identification, implement ISO 42001 for management system, and align with OECD principles for high-level governance. Map to EU AI Act requirements for specific regulatory compliance.', tags: ['nist-ai-rmf', 'iso-42001', 'standards', 'risk-management'] },
  { id: 'ai-engineer-responsible-ai-l4-028', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Dual Use', question: 'How should developers handle the dual-use potential of AI technologies?', options: ['Dual-use risks can be completely eliminated through technical measures', 'All AI technologies should be freely available without restrictions', 'Dual-use AI considerations: (1) face recognition (security vs surveillance), (2) language models (assistance vs misinformation), (3) deepfake technology (entertainment vs fraud), (4) autonomous systems (logistics vs weapons). Responsible practices: (1) pre-release risk assessment, (2) usage monitoring and enforcement of acceptable use policies, (3) technical safeguards (safety filters, watermarking), (4) controlled access for high-risk capabilities, (5) coordinated disclosure of vulnerabilities. The key challenge is maximizing beneficial uses while minimizing harmful ones without over-restricting technology', 'Dual-use considerations are only relevant for weapons'], correctAnswer: 2, explanation: 'Dual-use risk assessment framework: (1) Capability evaluation: what harmful uses could this technology enable? (voice cloning → fraud, code generation → malware, image generation → CSAM). (2) Accessibility assessment: who can access this capability? (API-only with ToS vs open-weights vs published paper with code). (3) Marginal risk: does this technology significantly increase capability beyond existing alternatives? (if Google already exists for finding harmful information, does a chatbot add meaningful risk?). (4) Mitigation feasibility: can effective safeguards be implemented? (content filters for image generation are moderately effective). (5) Benefit analysis: what valuable uses would be prevented by restricting the technology? Staged release: Anthropic, OpenAI, and Google use tiered access (research → limited beta → public) with safety evaluation at each stage. For open-source: once released, cannot be controlled. Pre-release safety testing is critical. Meta\'s LLaMA release strategy (open weights with acceptable use license) represents one approach to balancing openness and safety.', tags: ['dual-use', 'risk-assessment', 'staged-release', 'safeguards'] },
  { id: 'ai-engineer-responsible-ai-l4-029', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Accessibility', question: 'How should AI systems be designed for accessibility and inclusion?', options: ['Accessible AI design: (1) visual: image descriptions, high-contrast UI, screen reader compatibility, alt-text generation, (2) auditory: captions, sign language generation, speech-to-text, (3) motor: voice control, simplified interactions, adaptive interfaces, (4) cognitive: plain language explanations, consistent interfaces, error prevention. AI-powered accessibility: automatic image captioning for blind users, real-time captioning for deaf users, and simplified text generation for cognitive accessibility. AI evaluation must include: testing with assistive technologies and users with disabilities', 'Accessibility is only about visual impairments', 'AI accessibility is only required by law for government websites', 'Standard UI testing covers all accessibility needs'], correctAnswer: 0, explanation: 'AI for accessibility: (1) Be My Eyes + GPT-4V: visual assistance for blind users through image description. (2) Whisper + real-time captioning: deaf/hard-of-hearing access to conversations. (3) Sign language generation: AI generates sign language avatars from text (still research stage). (4) Simplified text: LLMs rewrite complex text into plain language for cognitive accessibility. AI accessibility requirements: (1) WCAG 2.1 Level AA compliance for AI-powered interfaces, (2) alternative input methods (voice, gesture) for motor-impaired users, (3) error recovery that doesn\'t rely solely on visual feedback. Testing: (1) automated accessibility testing (axe, Lighthouse), (2) screen reader testing with NVDA/VoiceOver, (3) user testing with people with disabilities (essential — automated tests miss real-world barriers). Inclusive evaluation: if your model is less accurate for ASL users, speech-impaired users, or users with non-standard typing patterns, it fails accessibility standards.', tags: ['accessibility', 'inclusion', 'wcag', 'assistive-technology'] },
  { id: 'ai-engineer-responsible-ai-l4-030', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Impact Assessment', question: 'What is an Algorithmic Impact Assessment (AIA) and when should it be conducted?', options: ['An AIA systematically evaluates the potential impacts of an AI system before deployment: (1) system description and purpose, (2) affected stakeholders and populations, (3) data assessment (sources, representativeness, quality), (4) fairness analysis (potential for disparate impact), (5) privacy assessment (data collection, storage, and use), (6) risk mitigation plan, (7) monitoring plan for post-deployment. AIAs should be conducted: before any AI system that makes decisions affecting people, and updated when the system significantly changes. They are becoming legally required in some jurisdictions (Canada, EU)', 'AIAs are only required by the Canadian government', 'AIAs only need to assess technical performance metrics', 'Impact assessments are only needed for criminal justice AI'], correctAnswer: 0, explanation: 'AIA framework: (1) Context: What decisions does the system make? Who is affected? What are the stakes? (2) Data: What data is used? Is it representative? Are there known gaps or biases? (3) Model: What type of model? How was it validated? What are known limitations? (4) Fairness: Has disparate impact been tested across relevant protected groups? What fairness definition is used and why? (5) Privacy: What personal data is processed? What protections are in place? (6) Human oversight: Who reviews automated decisions? When can decisions be overridden? (7) Accountability: Who is responsible for system outcomes? What happens when errors occur? (8) Monitoring: How will performance and fairness be tracked post-deployment? Canadian Directive on Automated Decision-Making requires AIAs for government systems. EU AI Act requires "fundamental rights impact assessments" for high-risk systems. NIST AI RMF provides a complementary framework for risk assessment.', tags: ['impact-assessment', 'aia', 'risk-evaluation', 'stakeholder-analysis'] },
  { id: 'ai-engineer-responsible-ai-l4-031', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Content Moderation', question: 'What are the fairness challenges in AI-powered content moderation?', options: ['Content moderation fairness challenges: (1) dialectal bias: AAE (African American English) is flagged as toxic more often than standard English with similar content, (2) language coverage: moderation is less effective in low-resource languages, (3) cultural context: humor, sarcasm, and reclaimed slurs vary across cultures and are misclassified, (4) over-moderation of marginalized voices: discussions about discrimination are flagged as containing the discriminatory language they discuss, (5) under-moderation of coded language: dog whistles and in-group coded harassment are missed. Addressing these requires diverse moderation teams, culturally-aware classifiers, and appeals processes', 'Content moderation does not have fairness implications', 'Automated moderation is always fairer than human moderation', 'AI content moderation is perfectly fair across all groups'], correctAnswer: 0, explanation: 'Documented disparities: (1) Sap et al. (2019): toxicity classifiers are 1.5x more likely to flag tweets in AAE as toxic compared to Standard American English with similar meaning. (2) Facebook\'s own audit revealed content moderation was less effective in languages other than English, contributing to hate speech propagation in Myanmar and Ethiopia. (3) "I am gay" flagged as toxic by some classifiers because "gay" appears in hateful contexts in training data. (4) Counter-speech ("racism is wrong") contains the word "racism" and may be flagged. Solutions: (1) dialect-aware training data that includes diverse English varieties, (2) contextual models that understand intent (discussing racism ≠ promoting it), (3) culturally-specific classifiers for different regions, (4) human appeals process with diverse moderators, (5) evaluation disaggregated by dialect, language, and demographic group. Content moderation is inherently a fairness challenge because the boundary between acceptable and unacceptable speech is culturally contextual.', tags: ['content-moderation', 'dialectal-bias', 'cultural-context', 'over-moderation'] },
  { id: 'ai-engineer-responsible-ai-l4-032', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Synthetic Media', question: 'What responsible practices should govern the development and deployment of generative AI?', options: ['Generated content should never be labeled as AI-created', 'Responsible generative AI practices: (1) provenance: embed C2PA content credentials or invisible watermarks (SynthID) in all generated content, (2) consent: do not generate likenesses of real people without consent, (3) transparency: clearly label AI-generated content, (4) safety: implement NSFW classifiers on both inputs and outputs, (5) copyright: respect opt-outs, avoid training on non-licensed content where possible, (6) monitoring: track and address misuse through user reporting and automated detection, (7) access control: limit capabilities that pose high misuse risk. These practices balance innovation with preventing harm from deepfakes, misinformation, and non-consensual imagery', 'Generative AI needs no responsible practices', 'Content provenance cannot be technically implemented'], correctAnswer: 1, explanation: 'Best practices in detail: (1) C2PA (Coalition for Content Provenance and Authenticity): cryptographic metadata embedded in image/video files recording: who created it, when, with what tool, and all edits. Adobe, Microsoft, Intel, BBC are members. (2) Invisible watermarking: SynthID (Google) embeds imperceptible patterns in generated images that survive cropping, compression, and screenshots. Detectable by the SynthID reader but invisible to humans. (3) Face generation limits: Midjourney, DALL-E block generation of photorealistic faces of real people. (4) NSFW safety: multi-stage safety — input text classifier + output image classifier + human review for flagged content. (5) Takedown process: reporting mechanism for people who find unauthorized synthetic content of themselves. (6) Research: invest in detection tools (deepfake detection, provenance verification) alongside generation capability. EU AI Act Article 52: AI-generated content must be labeled. Several US states have deepfake laws. The responsible AI ecosystem must evolve as fast as the generative capability.', tags: ['responsible-generative-ai', 'c2pa', 'watermarking', 'content-provenance'] },
  { id: 'ai-engineer-responsible-ai-l4-033', language: 'ai-engineer', level: 'level4', category: 'Responsible AI', subcategory: 'Future Challenges', question: 'What are the emerging responsible AI challenges as models become more capable?', options: ['Current governance frameworks are sufficient for all future AI systems', 'AI safety challenges are decreasing as models improve', 'Emerging challenges: (1) autonomous agents making consequential decisions without human review, (2) persuasion capabilities enabling manipulation at scale, (3) capability overhang — models may have dangerous capabilities that are undiscovered until triggered, (4) concentration of power in a few organizations controlling the most capable models, (5) environmental costs scaling with model size, (6) model organisms of misalignment — as models get smarter, alignment techniques that worked for weaker models may fail. Addressing these requires proactive governance, international cooperation, and investment in alignment and safety research proportional to capability development', 'More capable models have fewer responsible AI challenges'], correctAnswer: 2, explanation: 'Near-term (1-3 years): (1) Agent safety: LLM-powered agents taking irreversible actions (financial transactions, code deployment) without adequate human oversight. (2) Deepfake epidemic: real-time voice cloning + video generation enabling widespread fraud and misinformation. (3) Economic disruption: rapid automation of knowledge work outpacing workforce adaptation. Medium-term (3-10 years): (1) Autonomous decision systems: AI making complex decisions in healthcare, law, finance with minimal human involvement. (2) Recursive self-improvement: AI systems improving their own training data and algorithms. (3) Concentration: a few organizations controlling models that are economic necessities. Long-term: (1) Alignment at scale: ensuring AI systems with superhuman capabilities remain aligned with human values. (2) Global governance: international frameworks for managing transformative AI. The key principle: safety and governance investment should scale proportionally with capability advancement, not lag behind it.', tags: ['emerging-challenges', 'autonomous-agents', 'power-concentration', 'alignment-scaling'] },
];

export default questions;
